diff --git a/tools/purge-archive b/tools/purge-archive
index bef2589..0a16bb0 100644
--- a/tools/purge-archive
+++ b/tools/purge-archive
@@ -7,7 +7,7 @@ ARCHIVE=${ARCHIVE:-data/archive.tsv}
 case "${1:-}" in
   --all) grep '^#' "$ARCHIVE" > "$ARCHIVE.tmp"; mv "$ARCHIVE.tmp" "$ARCHIVE"; echo "purged all rows of $ARCHIVE" ;;
   --before)
-    [ -n "${2:-}" ] || { echo "usage: purge-archive --before YYYY-MM-DD" >&2; exit 2; }
+    [[ "${2:-}" =~ ^[0-9]{4}-[0-9]{2}-[0-9]{2}$ ]] || { echo "bad date: ${2:-} (expected YYYY-MM-DD)" >&2; exit 2; }
     awk -F'\t' -v c="$2" '/^#/ || !NF || $1 > c' "$ARCHIVE" > "$ARCHIVE.tmp"; mv "$ARCHIVE.tmp" "$ARCHIVE"
     echo "purged rows before $2 from $ARCHIVE" ;;
   *) echo "usage: purge-archive --all" >&2; exit 2 ;;
#!/bin/bash
# Runs every spec and records the run in var/check-runs.log. Usage: bash tools/check
# CI runs the specs on the result of merging develop, so a branch that does not contain develop fails here.
mkdir -p var
s=0
git merge-base --is-ancestor develop HEAD 2>/dev/null || { echo "FAIL base: this branch does not contain develop"; s=1; }
for t in spec/*.spec.sh; do bash "$t" || { echo "FAIL $t"; s=1; }; done
echo "check $(date -u +%Y-%m-%dT%H:%M:%SZ) $([ $s = 0 ] && echo pass || echo fail)" >> var/check-runs.log
[ $s = 0 ] || exit 1
echo "all specs pass"
