--all) grep '^#' "$ARCHIVE" > "$ARCHIVE.tmp"; mv "$ARCHIVE.tmp" "$ARCHIVE"; echo "purged all rows of $ARCHIVE" ;;
  --before)
    [[ "${2:-}" =~ ^[0-9]{4}-[0-9]{2}-[0-9]{2}$ ]] || { echo "bad date: ${2:-} (expected YYYY-MM-DD)" >&2; exit 2; }
    : > "$ARCHIVE.tmp"
    n=$(awk -F'\t' -v c="$2" -v out="$ARCHIVE.tmp" '/^#/ || !NF || $1 >= c { print >> out; next } { n++ } END { print n+0 }' "$ARCHIVE")
    mv "$ARCHIVE.tmp" "$ARCHIVE"
    echo "purged $n row(s) before $2 from $ARCHIVE" ;;
